(function(root){
  'use strict';

  const TERMS=Object.freeze([
    "By signing this document, the supplier agrees to deliver every item detailed herein on the date stated as the Purchase Order 'Delivery Date'.",
    'The supplier agrees to submit finish samples, shop drawings and/or prototypes for review by the interior designer and/or client.',
    'The supplier must obtain approval from the interior designer and/or client for finish samples, shop drawings and prototypes before production begins. Starting production without approval may cause the final product to be rejected upon delivery.',
    'The client, interior designer and/or purchasing agent (HPG International Latinoamericana) may visit the factory where the merchandise is produced after prior coordination with the supplier.',
    'The supplier must provide the product warranty letter, technical data sheet, certifications, care guide and maintenance manual. For textiles, the applicable flame-retardancy certification must also be provided.',
    'All merchandise must be properly packed and labeled with the side mark shown on this Purchase Order so the product interior is protected and each item is easy to identify during dispatch and installation.',
    'The supplier will notify HPG International Latinoamericana when the merchandise is ready for delivery.',
    'All deliveries require prior coordination with the purchasing agent (HPG International Latinoamericana SAC). Failure to comply allows the client to refuse the merchandise, and any additional rescheduling cost will be borne by the supplier.',
    'The supplier is responsible for removing all packing and packaging materials associated with every delivered item.',
    'When client-supplied textiles are used, the supplier must verify that the material is free of manufacturing defects before cutting. Any defect must be reported to the purchasing agent immediately.',
    'All items must be Contract quality and suitable for Contract use.',
    'The supplier must submit the signed delivery record together with the final invoice. Failure to submit the record may delay final payment.'
  ]);

  const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  const number=value=>{let parsed=Number(String(value??'').replace(/[^0-9.-]/g,''));return Number.isFinite(parsed)?parsed:0};
  const moneyApi=root.VAAKMoney||(typeof module==='object'&&module.exports?require('./money-utils.js'):null);
  const amount=value=>moneyApi?moneyApi.round(value):Math.round(number(value)*10)/10;
  const currencyLabel=currency=>currency==='$'?'US Dollars':currency==='S/'?'Soles':currency||'US Dollars';
  const money=(currency,value)=>`${currency||'$'}${amount(value).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
  const displayDate=value=>{let match=/^(\d{4})-(\d{2})-(\d{2})$/.exec(String(value||''));return match?`${match[2]}/${match[3]}/${match[1].slice(-2)}`:String(value||'')};
  const party=(label,name,data)=>`<div class="hpg-ref-party"><span class="hpg-ref-label">${label}</span><strong>${esc(name)}</strong><p>${esc(data.address||'')}</p><p>${data.contact||data.phone?`Contact: ${esc([data.contact,data.phone].filter(Boolean).join(' · '))}`:''}</p><p>${esc(data.email||'')}</p></div>`;
  function conditionsFor(order){if(Array.isArray(order.conditions))return order.conditions.map(String);if(typeof order.conditionsJson==='string'){try{let parsed=JSON.parse(order.conditionsJson);if(Array.isArray(parsed))return parsed.map(String)}catch{}}return TERMS}

  function render(order,context={}){
    let state=context.state||{},project=(state.projects||[]).find(item=>item.id===order.projectId)||{},specs=state.specs||[],suppliers=state.suppliers||[],supplierFor=name=>suppliers.find(item=>item.name===name)||{},supplierName=order.supplier||order.manufacturer||'',sourceName=order.source||order.manufacturer||'',supplier=supplierFor(supplierName),source=supplierFor(sourceName),partyData=(key,partySupplier)=>({address:order[`${key}Address`]||partySupplier.address||'',contact:order[`${key}Contact`]||partySupplier.contactName||partySupplier.contact||'',phone:order[`${key}Phone`]||partySupplier.phone||'',email:order[`${key}Email`]||partySupplier.email||''}),currency=order.amountCurrency||(order.items||[])[0]?.currency||'$',subtotal=amount((order.items||[]).reduce((sum,item)=>sum+amount(number(item.quantity)*amount(item.unitCost)),0)),taxType=['IGV','IVA','VAT'].includes(order.taxType)?order.taxType:'',taxAmount=taxType?amount(order.taxAmount):0,cif=amount(order.cifValue),total=amount(subtotal+taxAmount+cif),area=context.area||order.ocRubro||'',projectLine=[order.projectCode||project.code,project.name].filter(Boolean).join(' · '),sideMark=order.sideMark||project.name||'',preparedDate=context.dateFormatter?context.dateFormatter(order.date):order.date||'',itemRows=(order.items||[]).map(item=>{
      let spec=specs.find(candidate=>candidate.id===item.specId)||{},code=spec.code||spec.id||'',productCode=spec.productCode||'',image=spec.image||spec.photo||spec.imageUrl||'',title=item.description||spec.name||'',dimensions=spec.size||spec.dimensions||spec.measurements||'',material=spec.material||spec.finish||'',detail=spec.description&&spec.description!==material?spec.description:'',quantity=[item.quantity||'',spec.unit||item.unit||''].filter(Boolean).join(' '),unitCurrency=item.currency||currency,extension=amount(number(item.quantity)*amount(item.unitCost));
      return `<tr><td><strong class="hpg-ref-item-code">${esc(code)}</strong>${productCode?`<span class="hpg-ref-item-side-label">PRODUCT CODE</span><span>${esc(productCode)}</span>`:''}<span class="hpg-ref-item-side-label">SIDE MARK</span><span>${esc(sideMark)}</span><span>${esc([area,code].filter(Boolean).join(' '))}</span></td><td class="hpg-ref-image-cell">${image?`<img src="${esc(image)}" alt="${esc(title)}">`:''}</td><td><strong class="hpg-ref-item-title">${esc(title)}</strong>${dimensions?`<span>${esc(dimensions)}</span>`:''}${material?`<span>Material: ${esc(material)}</span>`:''}${detail?`<span>${esc(detail)}</span>`:''}</td><td class="hpg-ref-right">${esc(quantity)}</td><td class="hpg-ref-right">${money(unitCurrency,item.unitCost)}</td><td class="hpg-ref-right"><strong>${money(unitCurrency,extension)}</strong></td></tr>`
    }).join(''),shipAddress=order.shipTo||order.warehouse||project.warehouse||'',billAddress=order.billTo||project.fiscal||'',freight=order.freight||'Included';

    return `<article class="hpg-po hpg-reference-po notranslate" translate="no" lang="en">
      <header class="hpg-ref-header"><img src="assets/hpg-international-reference.png" alt="HPG International Latinoamericana"><div><span>AS AGENT</span><h1>PURCHASE ORDER</h1><strong>${esc(projectLine)}</strong></div></header>
      <section class="hpg-ref-summary"><div class="hpg-ref-number"><span>PO NUMBER</span><strong>${esc(order.number)}</strong></div><div><span>PROJECT</span><strong>${esc(projectLine)}</strong><p>Area: ${esc(area)}</p></div><div><span>PROJECT CONTACT</span><strong>Julia Díaz</strong><p>+51 12421762 · julia.dias@hpgilatam.com</p></div></section>
      <h2 class="hpg-ref-section-label">PARTIES</h2>
      <section class="hpg-ref-parties">${party('MANUFACTURER',supplierName,partyData('supplier',supplier))}${party('SOURCE',sourceName,partyData('source',source))}<div class="hpg-ref-party"><span class="hpg-ref-label">SHIP TO</span><strong>${esc(project.legal||project.name||'')}</strong><p>${esc(shipAddress)}</p>${order.destination?`<p>Final Destination: ${esc(order.destination)}</p>`:''}</div><div class="hpg-ref-party"><span class="hpg-ref-label">BILL TO</span><strong>${esc(project.legal||project.name||'')}</strong><p>${esc(billAddress)}</p><p class="hpg-ref-warning">*DO NOT SHIP TO BILL TO ADDRESS UNLESS OTHERWISE STATED</p></div></section>
      <h2 class="hpg-ref-section-label">COMMERCIAL TERMS</h2>
      <section class="hpg-ref-commercial"><div><span>INCOTERM</span><strong>${esc(order.incoterm||order.shippingInstructions||'')}</strong></div><div><span>DELIVERY DATE</span><strong>${esc(displayDate(order.deliveryDate))}</strong></div><div><span>FREIGHT</span><strong>${esc(freight)}</strong></div><div><span>TERMS</span><strong>${esc(order.terms||'')}</strong></div><div><span>CURRENCY</span><strong>${esc(currencyLabel(currency))}</strong></div><div><span>SPECIFIED BY</span><strong>${esc(order.specifiedBy||'')}</strong></div></section>
      <section class="hpg-ref-marks"><div><span>SIDE MARK</span><strong>${esc(sideMark)}</strong></div><div><span>PREP BY / DATE</span><strong>${esc([order.preparedBy||'',preparedDate].filter(Boolean).join(' / '))}</strong></div><div class="hpg-ref-total"><span>PO TOTAL</span><strong>${money(currency,total)}</strong></div></section>
      <table class="hpg-ref-items"><thead><tr><th>ITEM</th><th>IMAGE</th><th>DESCRIPTION</th><th>QTY</th><th>UNIT COST</th><th>TOTAL COST</th></tr></thead><tbody>${itemRows}</tbody></table>
      <section class="hpg-ref-totals"><h2 class="hpg-ref-section-label">TOTALS &amp; COMMERCIAL TERMS</h2><div class="hpg-ref-totals-lines"><p><span>Subtotal</span><strong>${money(currency,subtotal)}</strong></p><p class="hpg-ref-tax"><span>${esc(taxType||'TAX')}</span><strong>${money(currency,taxAmount)}</strong></p><p><span>CIF Value</span><strong>${money(currency,cif)}</strong></p><p class="hpg-ref-total"><span>PO TOTAL</span><strong>${money(currency,total)}</strong></p></div></section>
      <section class="hpg-ref-payment"><p><span>PAYMENT TERMS</span>${esc(order.paymentTerms||'')}</p><p><span>PRODUCTION TIME</span>${esc(order.productionTime||'')}</p><p><span>WARRANTY</span>${esc(order.warranty||'')}</p></section>
      <p class="hpg-ref-note">* For all items, shop drawings and finish samples must be approved before production begins.</p>
      <section class="hpg-ref-approvals-section"><h2 class="hpg-ref-section-label">APPROVALS</h2><div class="hpg-ref-approvals"><div><span>APPROVED BY</span><p>${esc(order.approvedBy||'')}</p><i></i><small>Signature (Title)<b>Date</b></small></div><div><span>ACCEPTED BY VENDOR</span><p>${esc(supplierName)} Company Name</p><i></i><small>Signature (Title)<b>Date</b></small></div><div><span>AGENT / ENTITY</span><p>HPG International Latinoamericana SAC</p><i></i><small>Signature<b>Date</b></small></div><div class="hpg-ref-approved-for"><span>APPROVED FOR</span><strong>${money(currency,total)}</strong><small>Shipping Date: ______________ &nbsp; Approved: ______________</small></div></div></section>
      <section class="hpg-ref-conditions"><h2>TERMS AND CONDITIONS</h2><h3>STANDARD PURCHASE CONDITIONS</h3><div>${conditionsFor(order).map((term,index)=>`<p><strong>${String(index+1).padStart(2,'0')}</strong><span>${esc(term)}</span></p>`).join('')}</div></section>
      <footer class="hpg-ref-footer"><span>HPG International Latinoamericana SAC · RUC 20600893123 · hpgilatam.com</span><span>PO ${esc(order.number)}</span></footer>
    </article>`
  }

  root.VAAKPurchaseOrderTemplate=Object.freeze({render,defaultTerms:TERMS});
})(typeof globalThis!=='undefined'?globalThis:this);
